part of 'network_session.dart';

/// The parsed `dm:user:<uid>:<agent>@<device>` virtual channel id.
typedef DmChannelParts = ({String userId, String agentName, String deviceId});

/// Parses a DM channel id; null on any shape violation.
DmChannelParts? parseDmChannelId(String channelId) {
  if (!channelId.startsWith('dm:user:')) return null;
  final rest = channelId.substring('dm:user:'.length);
  final colon = rest.indexOf(':');
  if (colon <= 0) return null;
  final at = rest.indexOf('@', colon);
  if (at < 0 || at + 1 >= rest.length) return null;
  return (
    userId: rest.substring(0, colon),
    agentName: rest.substring(colon + 1, at),
    deviceId: rest.substring(at + 1),
  );
}

/// Human-facing peer label for a DM virtual channel. The wire id belongs
/// in routing logs, not in the page title or composer hint. A roster tap
/// supplies its richer device label; inbox/history restores use a generic
/// human label rather than leaking the stable device id from the channel id.
String dmChannelPeerLabel(String channelId, {String? deviceLabel}) {
  final parts = parseDmChannelId(channelId);
  if (parts == null) return channelDisplayLabel(channelId);
  var device = deviceLabel?.trim() ?? '';
  // Restored channel rows historically persisted the WHOLE label in `name`.
  // Accept that form without duplicating the agent suffix, and recognize the
  // old raw-device fallback so it is upgraded instead of shown again.
  final agentSuffix = ' · ${parts.agentName}';
  if (device.endsWith(agentSuffix)) {
    device = device.substring(0, device.length - agentSuffix.length).trim();
  }
  if (device == parts.deviceId) device = '';
  return '${device.isEmpty ? 'Device' : device} · '
      '${parts.agentName}'; // l10n:ignore
}

/// The DM branches of [NetworkSession]. One personal-network session can
/// carry any number of DM conversations next to its regular channels.
extension NetworkSessionDm on NetworkSession {
  /// Per-channel remote session target for the next DM send (the tapped
  /// roster session; null = the device's active/latest session).
  Map<String, String?> get dmSessionTargets => _dmSessionTargets;

  /// Selects the visible DM thread and synchronously notifies open panes.
  /// Null selects the device-general bucket for legacy/session-less rows.
  void selectDmSession(String channelId, String? sessionId, {String? title}) {
    final normalizedTitle = title?.trim();
    if (_dmSessionTargets[channelId] == sessionId &&
        _dmSessionTitles[channelId] == normalizedTitle) {
      return;
    }
    _dmSessionTargets[channelId] = sessionId;
    _dmSessionTitles[channelId] = normalizedTitle?.isEmpty == true
        ? null
        : normalizedTitle;
    notifyDmChanged();
  }

  /// Human title for the selected DM thread, or null for the device header.
  String? dmSessionTitle(String channelId) => _dmSessionTitles[channelId];

  /// Attaches the app-scope device connector: DM sends route through it
  /// and its live device-WS mail feeds the open DM channel stores.
  void attachDmConnector(DeviceConnectorService connector) {
    if (identical(_dmConnector, connector)) return;
    _dmConnector = connector;
    unawaited(_dmSubscription?.cancel());
    _dmSubscription = connector.dmMail.listen(_onDmMail);
  }

  /// Synthetic channel metadata. DM history rides
  /// `GET /api/channels/{dm:id}/messages` (owner-only server branch);
  /// live frames arrive on the account network WS and device connector,
  /// with [ChannelState.seen] deduplicating the two delivery paths.
  /// A roster-supplied [deviceLabel] also upgrades older generic/raw labels.
  void prepareDmChannel(String channelId, {String? deviceLabel}) {
    final label = dmChannelPeerLabel(channelId, deviceLabel: deviceLabel);
    final index = channels.indexWhere((channel) => channel.id == channelId);
    if (index < 0) {
      channels = [
        ...channels,
        Channel(id: channelId, networkId: networkId, name: label),
      ];
    } else if (deviceLabel?.trim().isNotEmpty == true &&
        channels[index].name != label) {
      final previous = channels[index];
      final updated = [...channels];
      updated[index] = Channel(
        id: previous.id,
        networkId: previous.networkId,
        name: label,
        isPublic: previous.isPublic,
        acl: previous.acl,
        retentionDays: previous.retentionDays,
      );
      channels = updated;
    }
    _ensureDmPolling();
  }

  /// The backend persists user/agent DM mail but currently does not push the
  /// user-addressed half to either live socket. Poll only OPEN DM stores as a
  /// v1 fallback; real network/device frames still win through the same
  /// envelope-id dedup. One guarded timer serves every open DM in this session.
  void _ensureDmPolling() {
    if (_dmPollTimer?.isActive ?? false) return;
    _dmPollTimer = Timer.periodic(const Duration(seconds: 5), (_) {
      unawaited(_pollOpenDmChannels());
    });
  }

  @visibleForTesting
  Future<void> debugPollDmChannels() => _pollOpenDmChannels();

  Future<void> _pollOpenDmChannels() async {
    if (_dmPollInFlight) return;
    final open = channelStates.entries
        .where((entry) => isDmChannel(entry.key))
        .toList(growable: false);
    if (open.isEmpty) {
      _dmPollTimer?.cancel();
      _dmPollTimer = null;
      return;
    }
    _dmPollInFlight = true;
    try {
      for (final entry in open) {
        if (_dmPollTimer == null) return; // closed while a request was away
        try {
          await _pollDmChannel(entry.key, entry.value);
        } on Object catch (error) {
          // A transient REST/decode failure must not kill later ticks or
          // become an unhandled Timer exception.
          debugPrint('[dm] history poll failed ${entry.key}: $error');
        }
      }
    } finally {
      _dmPollInFlight = false;
    }
  }

  Future<void> _pollDmChannel(String channelId, ChannelState state) async {
    final revision = state._revision;
    final page = await _client.listMessages(channelId, useAccountToken: true);
    var changed = false;
    for (final envelope in page.items) {
      if (state.seen.contains(envelope.id)) continue;
      final message = await _decode(envelope);
      if (!_isCurrentChannelState(channelId, state, revision) ||
          _dmPollTimer == null) {
        return;
      }
      // Unlike initial history pagination, a poll MERGES the newest tail:
      // state.add appends after the outgoing message and owns race dedup
      // against either live socket path.
      if (state.add(message)) changed = true;
    }
    if (changed) notifyDmChanged();
  }

  Future<void> sendDmText(String channelId, String text) async {
    final connector = _dmConnector;
    final parts = parseDmChannelId(channelId);
    if (connector == null || parts == null) {
      throw StateError('DM connector not attached for $channelId');
    }
    if (!_wallet.hasIdentity) {
      await _wallet.createIfMissing(displayName: identity.displayName);
    }
    final sessionId = _dmSessionTargets[channelId];
    final msgId = await connector.sendDmToAgent(
      deviceId: parts.deviceId,
      agentName: parts.agentName,
      sessionId: sessionId,
      text: text,
    );
    _dmOwnText[msgId] = text;
    _dmOwnSessionIds[msgId] = sessionId;
    final state = channelStates.putIfAbsent(channelId, ChannelState.new);
    state.add(
      ChannelMessage(
        envelopeId: msgId,
        senderId: identity.id,
        senderPub: _wallet.identityPub ?? '',
        text: text,
        isOwn: true,
        createdAt: DateTime.now().toUtc(),
        sessionId: sessionId,
      ),
    );
    notifyDmChanged();
  }

  /// Decrypts one DM history/realtime row: my own frames were sealed
  /// with DH(myPriv, agentPub) — the peer's roster dmPub recomputes the
  /// shared key; their frames carry the sender pubkey in the header.
  Future<ChannelMessage> decodeDmEnvelope(Envelope envelope) async {
    final connector = _dmConnector;
    final parts = parseDmChannelId(envelope.channelId);
    final myId = connector == null ? null : await connector.accountUserId();
    final frame = hubTryOpenFanet1(envelope.payload);
    // The live backend rewrites ANY authenticated sender to the bare
    // account uid — including an agent's `name@deviceId` — so senderId
    // alone cannot tell my own DM from the agent's reply (owner feedback:
    // replies rendered as outgoing rows with the OWNER's display name).
    // The frame's sender pubkey can: a DM channel has exactly two
    // possible sealers, the local wallet and the peer agent. Comparing
    // against the LOCAL identity pubkey is roster-independent (review
    // #2197) — a roster eviction mid-chat previously nullified the
    // roster dmPub comparison and degraded replies to outgoing rows.
    final isAgentFrame = _isPeerAgentFrame(frame);
    final isOwn =
        (envelope.senderId == myId || envelope.senderId == 'user:$myId') &&
        !isAgentFrame;
    final sentText = isOwn ? _dmOwnText[envelope.id] : null;
    if (sentText != null) {
      return ChannelMessage(
        envelopeId: envelope.id,
        senderId: envelope.senderId,
        senderPub: _wallet.identityPub ?? '',
        senderName: identity.displayName,
        text: sentText,
        isOwn: true,
        createdAt: envelope.createdAt,
        sessionId: _dmOwnSessionIds[envelope.id],
      );
    }
    final senderPub = isOwn
        ? await _dmPeerPubkey(connector, parts)
        : frame?.senderPubkey;
    String? text;
    String? sessionId;
    var senderPubB64 = '';
    if (frame != null && senderPub != null) {
      try {
        final plaintext = await hubDecryptPayloadWithKeyPair(
          recipientDhKeyPair: await _wallet.identityKeyPair(),
          senderDhPubkey: senderPub,
          frameId: envelope.id,
          aadTarget: envelope.channelId,
          ciphertextB64: frame.ciphertextB64,
        );
        final decoded = _unwrapDmText(plaintext);
        text = decoded.text;
        sessionId = decoded.sessionId;
        senderPubB64 = base64Encode(senderPub.bytes);
      } on Object {
        text = null; // wrong key epoch / legacy shape — placeholder row
      }
    }
    return ChannelMessage(
      envelopeId: envelope.id,
      senderId: envelope.senderId,
      senderPub: senderPubB64,
      senderName: isOwn
          ? identity.displayName
          : _agentSenderLabel(envelope.channelId, parts, sessionId),
      text: text,
      isOwn: isOwn,
      createdAt: envelope.createdAt,
      sessionId: sessionId,
    );
  }

  Future<SimplePublicKey?> _dmPeerPubkey(
    DeviceConnectorService? connector,
    DmChannelParts? parts,
  ) async {
    if (connector == null || parts == null) return null;
    final pub = connector.agentDmPub(
      deviceId: parts.deviceId,
      agentName: parts.agentName,
    );
    if (pub == null) return null;
    return SimplePublicKey(base64Decode(pub), type: KeyPairType.x25519);
  }

  /// True when the frame was NOT sealed by this device's wallet
  /// identity — i.e. the peer agent's reply. A DM channel has exactly
  /// two possible sealers (the local wallet and the peer agent), so
  /// comparing the frame's sender pubkey header against the local
  /// identity pubkey needs no roster lookup and cannot degrade when
  /// the roster evicts the peer entry mid-chat (review #2197).
  bool _isPeerAgentFrame(HubFanet1Frame? frame) {
    final senderPub = frame?.senderPubkey;
    final myPub = _wallet.identityPub;
    if (senderPub == null || myPub == null) return false;
    return base64Encode(senderPub.bytes) != myPub;
  }

  /// Incoming DM sender label: the tapped session's human title when this
  /// row belongs to it, otherwise 'fa' for the default app agent ('main'
  /// is an internal address part, not a display name) or the agent name.
  String? _agentSenderLabel(
    String channelId,
    DmChannelParts? parts,
    String? sessionId,
  ) {
    if (sessionId != null &&
        sessionId == _dmSessionTargets[channelId] &&
        _dmSessionTitles[channelId] != null) {
      return _dmSessionTitles[channelId];
    }
    final name = parts?.agentName;
    if (name == null || name.isEmpty) return null;
    return name == 'main' ? 'fa' : name;
  }

  /// Thread-aware DM plaintext is `{"text": …, "sessionId"?}` in both
  /// directions. Legacy raw assistant text and malformed wrappers pass
  /// through unchanged and therefore land in the device-general bucket.
  ({String text, String? sessionId}) _unwrapDmText(String plaintext) {
    if (!plaintext.startsWith('{')) return (text: plaintext, sessionId: null);
    try {
      final decoded = jsonDecode(plaintext);
      if (decoded is Map && decoded['text'] is String) {
        final sessionId = decoded['sessionId'];
        return (
          text: decoded['text'] as String,
          sessionId: sessionId is String && sessionId.isNotEmpty
              ? sessionId
              : null,
        );
      }
    } on FormatException {
      // Raw text also decrypts here — keep it as-is.
    }
    return (text: plaintext, sessionId: null);
  }

  void _onDmMail(NetworkEnvelope envelope) {
    final channelId = envelope.channel;
    final ciphertext = envelope.ciphertext;
    if (channelId == null || ciphertext == null) return;
    final state = channelStates[channelId];
    // state.add owns the dedup (seen.add on success) — pre-marking here
    // would make the decoded append a no-op. A contains-check only
    // short-circuits the common redelivery case.
    if (state == null || state.seen.contains(envelope.msgId)) return;
    final ts = DateTime.tryParse(envelope.ts);
    unawaited(
      decodeDmEnvelope(
            Envelope(
              id: envelope.msgId,
              channelId: channelId,
              senderId: envelope.from ?? '',
              payload: ciphertext,
              createdAt: ts,
            ),
          )
          .then((message) {
            if (!identical(channelStates[channelId], state)) return;
            if (state.add(message)) notifyDmChanged();
          })
          .catchError((Object error) {
            // A live DM must never vanish silently (e2e issue #2062).
            debugPrint('[dm] live decode failed ${envelope.msgId}: $error');
          }),
    );
  }
}

import 'dart:async';
import 'dart:convert';

import 'package:cryptography/cryptography.dart';
import 'package:fa/network/channel_chat_service.dart';
import 'package:fa/network/device_connector_service.dart';
import 'package:fa/network/key_wallet.dart';
import 'package:fa/network/envelope_codec.dart';
import 'package:fa/network/models.dart';
import 'package:fa/network/network_session.dart';
import 'package:fa/ui/network/network_chat_page.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show AgentRunState, NetworkEnvelope, NetworkEnvelopeKind;
// The fanet1 DM primitives are pure Dart in the messaging core.
// ignore: implementation_imports
import 'package:flutter_agent_harness/src/messaging/hub_crypto.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fakes.dart';

const dmChannel = 'dm:user:u-1:fa@dev-1';

final class FakeDmConnector implements DeviceConnectorService {
  final dmMailController = StreamController<NetworkEnvelope>.broadcast();
  final sent =
      <({String deviceId, String agentName, String? sessionId, String text})>[];
  String? peerDmPub;
  Future<String> Function()? accountUserIdHandler;

  @override
  Stream<NetworkEnvelope> get dmMail => dmMailController.stream;

  @override
  Future<String> accountUserId() =>
      accountUserIdHandler?.call() ?? Future<String>.value('u-1');

  @override
  String? agentDmPub({required String deviceId, required String agentName}) =>
      peerDmPub;

  /// The DM working-banner state: null (hidden) unless a test seeds it.
  AgentRunState? peerRunState;

  @override
  AgentRunState? agentRunState(
    String agentAddress, {
    required String networkId,
  }) => peerRunState;

  @override
  Stream<NetworkEnvelope> get rosterFrames => const Stream.empty();

  @override
  Stream<NetworkEnvelope> get presenceFrames => const Stream.empty();

  @override
  Future<String> sendDmToAgent({
    required String deviceId,
    required String agentName,
    String? sessionId,
    required String text,
  }) async {
    sent.add((
      deviceId: deviceId,
      agentName: agentName,
      sessionId: sessionId,
      text: text,
    ));
    return 'dm-msg-1';
  }

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

NetworkEnvelope _dmMail({
  String msgId = 'dm-device-1',
  String? channel = dmChannel,
  String? ciphertext = 'not-a-fanet1-frame',
  String? from = 'fa@dev-1',
  String ts = '2026-11-14T10:00:00.000Z',
}) => NetworkEnvelope(
  kind: NetworkEnvelopeKind.mail,
  msgId: msgId,
  network: 'personal',
  channel: channel,
  from: from,
  to: 'user:u-1',
  ts: ts,
  ciphertext: ciphertext,
);

void main() {
  dmAgentBannerTransitionTests();
  group('parseDmChannelId', () {
    test('parses the virtual channel id and rejects malformed shapes', () {
      final parts = parseDmChannelId(dmChannel)!;
      expect(parts.userId, 'u-1');
      expect(parts.agentName, 'fa');
      expect(parts.deviceId, 'dev-1');
      expect(parseDmChannelId('c1'), isNull);
      expect(parseDmChannelId('dm:user:u-1'), isNull);
      expect(parseDmChannelId('dm:user:u-1:fa'), isNull);
      expect(parseDmChannelId('dm:user::fa@dev-1'), isNull);
    });

    test('peer label keeps the routing id out of composer/title text', () {
      // Raw device ids are never shown: the generic localized fallback
      // replaces them; a real roster label wins.
      expect(dmChannelPeerLabel(dmChannel), 'Device · fa');
      expect(
        dmChannelPeerLabel(dmChannel, deviceLabel: 'dev-1'),
        'Device · fa',
      );
      expect(dmChannelPeerLabel(dmChannel, deviceLabel: 'Duo'), 'Duo · fa');
    });
  });

  group('NetworkSession DM channels', () {
    late FakeHttpClient httpClient;
    late FakeWsConnector wsConnector;
    late FakeDmConnector dmConnector;
    late KeyWallet wallet;
    late ({String pub, String priv}) channelKeys;

    setUp(() async {
      httpClient = FakeHttpClient();
      wsConnector = FakeWsConnector();
      dmConnector = FakeDmConnector();
      channelKeys = await EnvelopeCodec.newX25519KeyPair();
      addTearDown(dmConnector.dmMailController.close);
    });

    Future<SimplePublicKey> identityPub() async => SimplePublicKey(
      base64Decode(wallet.identityPub!),
      type: KeyPairType.x25519,
    );

    Future<NetworkSession> session() async {
      wallet = await walletWithChannel(
        channelPub: channelKeys.pub,
        channelPriv: channelKeys.priv,
      );
      final s = buildSession(
        httpClient: httpClient,
        connector: wsConnector,
        wallet: wallet,
        jwtToken: 'jwt-account',
      );
      s.attachDmConnector(dmConnector);
      addTearDown(s.dispose);
      return s;
    }

    test(
      'openChannel adds synthetic metadata and resolves empty history',
      () async {
        httpClient.respond(200, body: '{"items":[],"nextCursor":""}');
        final s = await session();
        await s.openChannel(dmChannel);
        expect(s.channels.any((c) => c.id == dmChannel), isTrue);
        expect(s.channelStates[dmChannel]!.historyResolved, isTrue);
        expect(s.channelStates[dmChannel]!.messages, isEmpty);
        expect(
          httpClient.requests.single.headers['authorization'],
          'Bearer jwt-account',
        );
      },
    );

    test(
      'sendText routes through the connector and appends own message',
      () async {
        final s = await session();
        s.dmSessionTargets[dmChannel] = 'sess-1';
        await s.sendText(dmChannel, 'hello agent');
        expect(dmConnector.sent.single.deviceId, 'dev-1');
        expect(dmConnector.sent.single.agentName, 'fa');
        expect(dmConnector.sent.single.sessionId, 'sess-1');
        expect(dmConnector.sent.single.text, 'hello agent');
        final message = s.channelStates[dmChannel]!.messages.single;
        expect(message.envelopeId, 'dm-msg-1');
        expect(message.text, 'hello agent');
        expect(message.isOwn, isTrue);
      },
    );

    test('just-sent own text survives an undecryptable history echo', () async {
      final s = await session();
      await s.sendText(dmChannel, 'hello agent');
      // Simulate the account-WS echo before the peer roster key is available.
      final decoded = await s.decodeDmEnvelope(
        Envelope(
          id: 'dm-msg-1',
          channelId: dmChannel,
          senderId: 'u-1',
          payload: 'not-a-fanet1-frame',
        ),
      );
      expect(decoded.text, 'hello agent');
      expect(decoded.isOwn, isTrue);
      final chat = ChannelChatService(session: s, channelId: dmChannel);
      addTearDown(chat.dispose);
      expect(chat.messages.single.content, 'hello agent');
      expect(chat.messages.single.content, isNot(contains('Encrypted')));
    });

    test('history rows decrypt: agent reply and own wrapped text', () async {
      final s = await session();
      final userPub = await identityPub();
      final agentKeys = await X25519().newKeyPair();
      final agentPub = await agentKeys.extractPublicKey();
      dmConnector.peerDmPub = base64Encode(agentPub.bytes);

      // Agent → user frame (sealed to the user's identity pub).
      final reply = await hubSealFanet1(
        senderDhKeyPair: agentKeys,
        recipientDhPubkey: userPub,
        frameId: 'dm-a1',
        aadTarget: dmChannel,
        plaintext: 'pong from agent',
      );
      // User → agent own frame (sealed to the agent's dmPub, sender id
      // is the account user id — the server canonical form).
      final own = await hubSealFanet1(
        senderDhKeyPair: await wallet.identityKeyPair(),
        recipientDhPubkey: agentPub,
        frameId: 'dm-u1',
        aadTarget: dmChannel,
        plaintext: jsonEncode({'text': 'ping', 'sessionId': 'sess-1'}),
      );
      httpClient.respond(
        200,
        body: jsonEncode({
          'items': [
            {
              'id': 'dm-u1',
              'channelId': dmChannel,
              'senderId': 'u-1',
              'payload': own,
              'createdAt': '2026-11-14T10:00:00.000Z',
            },
            {
              'id': 'dm-a1',
              'channelId': dmChannel,
              'senderId': 'fa@dev-1',
              'payload': reply,
              'createdAt': '2026-11-14T10:00:01.000Z',
            },
          ],
          'nextCursor': '',
        }),
      );
      await s.openChannel(dmChannel);
      final messages = s.channelStates[dmChannel]!.messages;
      expect(messages, hasLength(2));
      expect(messages[0].text, 'ping');
      expect(messages[0].isOwn, isTrue);
      expect(messages[1].text, 'pong from agent');
      expect(messages[1].isOwn, isFalse);
      expect(messages[1].senderName, 'fa');
    });

    test('roster eviction mid-chat keeps agent replies classified', () async {
      // No peerDmPub seeded: the roster evicted the peer entry, so
      // agentDmPub resolves null — the reported degradation trigger.
      final s = await session();
      final userPub = await identityPub();
      final agentKeys = await X25519().newKeyPair();
      final agentPub = await agentKeys.extractPublicKey();
      // The live backend rewrites ANY authenticated sender to the bare
      // account uid — including the agent's — so both rows arrive with
      // MY sender id; only the frame's seal pubkey tells them apart.
      final reply = await hubSealFanet1(
        senderDhKeyPair: agentKeys,
        recipientDhPubkey: userPub,
        frameId: 'dm-a1',
        aadTarget: dmChannel,
        plaintext: 'pong after eviction',
      );
      final own = await hubSealFanet1(
        senderDhKeyPair: await wallet.identityKeyPair(),
        recipientDhPubkey: agentPub,
        frameId: 'dm-u1',
        aadTarget: dmChannel,
        plaintext: jsonEncode({'text': 'ping'}),
      );

      final decodedReply = await s.decodeDmEnvelope(
        Envelope(
          id: 'dm-a1',
          channelId: dmChannel,
          senderId: 'u-1',
          payload: reply,
        ),
      );
      expect(decodedReply.isOwn, isFalse);
      expect(decodedReply.text, 'pong after eviction');
      expect(decodedReply.senderName, 'fa');
      // Same rewritten sender id, but sealed with MY identity: stays own.
      final decodedOwn = await s.decodeDmEnvelope(
        Envelope(
          id: 'dm-u1',
          channelId: dmChannel,
          senderId: 'u-1',
          payload: own,
        ),
      );
      expect(decodedOwn.isOwn, isTrue);
    });

    test(
      'another device gets an honest placeholder in both directions',
      () async {
        await session();
        final originPub = await identityPub();
        final agentKeys = await X25519().newKeyPair();
        final agentPub = await agentKeys.extractPublicKey();
        dmConnector.peerDmPub = base64Encode(agentPub.bytes);
        final own = await hubSealFanet1(
          senderDhKeyPair: await wallet.identityKeyPair(),
          recipientDhPubkey: agentPub,
          frameId: 'dm-u1',
          aadTarget: dmChannel,
          plaintext: jsonEncode({'text': 'from Duo'}),
        );
        final reply = await hubSealFanet1(
          senderDhKeyPair: agentKeys,
          recipientDhPubkey: originPub,
          frameId: 'dm-a1',
          aadTarget: dmChannel,
          plaintext: 'reply to Duo',
        );
        // A second wallet models macOS: same account, different X25519 identity.
        final foreign = await session();
        expect(wallet.identityPub, isNot(base64Encode(originPub.bytes)));
        httpClient.respond(
          200,
          body: jsonEncode({
            'items': [
              {
                'id': 'dm-u1',
                'channelId': dmChannel,
                'senderId': 'u-1',
                'payload': own,
              },
              {
                'id': 'dm-a1',
                'channelId': dmChannel,
                'senderId': 'fa@dev-1',
                'payload': reply,
              },
            ],
            'nextCursor': '',
          }),
        );
        await foreign.openChannel(dmChannel);
        final stored = foreign.channelStates[dmChannel]!.messages;
        expect(stored, hasLength(2));
        expect(stored.map((message) => message.text), [isNull, isNull]);

        final chat = ChannelChatService(
          session: foreign,
          channelId: dmChannel,
